1:// The composer's model and thinking pickers (the Composer proposal on the
2:// "JusPrin v2" canvas, states 5 to 8). The model menu lists every model of
3:// every provider with a key, under the provider's name when there is more
4:// than one; the thinking menu lists the levels the chosen model accepts and
5:// is left out when it accepts none. A choice belongs to the active chat and
6:// applies from its next turn. A model menu of more than SEARCH_FROM models
7:// (OpenRouter's runs to hundreds) starts with a search field, and a provider
8:// with that many shows its count beside its name.
9://
10:// An account's models carry their price and what they are for; models on the
11:// person's own key name no price. A chat keeps the model and thinking level it
12:// started with, so once the person has sent a message both pickers are greyed,
13:// and hovering either says why and what a message costs.
14:
15:import { ChatModelChoice, CreditAccount, ModelCatalogPayload, ModelOptionInfo } from '../bridge/protocol';
16:import { messageCostSentence, priceWords } from '../credits';
17:import { ActionMenu, MenuItem, MenuSearch, MenuSection } from './ChatNavigation';
18:
19:const EFFORT_LABELS: Record<string, string> = {
20:  none: 'Off', minimal: 'Minimal', low: 'Low', medium: 'Medium', high: 'High', xhigh: 'Extra high', max: 'Max',
21:  // JusPrin's own levels, which its gateway maps to the model's.
22:  fast: 'Fast', thorough: 'Thorough',
23:};
24:
25:export const SEARCH_FROM = 12;
26:
27:const TIER_USES: Record<string, string> = {
28:  basic: 'setting up an ordinary print',
29:  expert: 'troubleshooting, tricky models, anything you’d ask a person',
30:};
31:
32:const MODEL_SEARCH: MenuSearch = { label: 'Search models', noMatch: (query) => `No models match “${query}”.` };
33:
34:export function effortLabel(effort: string): string {
35:  return EFFORT_LABELS[effort] ?? effort;
36:}
37:
38:// The catalog's entry for the chosen model, if its list has arrived.
39:export function findModel(catalog: ModelCatalogPayload, choice: ChatModelChoice): ModelOptionInfo | undefined {
40:  return catalog.providers.find((provider) => provider.id === choice.provider)?.models
41:    .find((model) => model.id === choice.model);
42:}
43:
44:// What the chosen model is called when its list has none of it. JusPrin's
45:// model ids are aliases ("slicer-1") that mean nothing to anyone, so until
46:// its list names the model the chat's model reads as JusPrin. Every other
47:// provider's id is the model's own name.
48:function unlistedLabel(catalog: ModelCatalogPayload, choice: ChatModelChoice): string {
49:  const provider = catalog.providers.find((option) => option.id === choice.provider);
50:  return provider && provider.id === 'jusprin' ? provider.label : choice.model;
51:}
52:
53:// What follows a provider's name above its models: what JusPrin's own AI is
54:// for, or how many models a long list holds.
55:function providerDetail(provider: ModelCatalogPayload['providers'][number]): string | undefined {
56:  if (provider.id === 'jusprin') return 'Specializes in 3D printing';
57:  return provider.models.length > SEARCH_FROM ? `${provider.models.length} models` : undefined;
58:}
59:
60:// Switching model keeps the thinking level when the new model has it, and
61:// otherwise leaves the level to the new model's default.
62:export function switchModel(choice: ChatModelChoice, provider: string, model: ModelOptionInfo): ChatModelChoice {
63:  return { provider, model: model.id, effort: model.efforts.includes(choice.effort) ? choice.effort : '' };
64:}
65:
66:export function modelMenu(catalog: ModelCatalogPayload, choice: ChatModelChoice,
67:  onChoose: (choice: ChatModelChoice) => void, account?: CreditAccount | null,
68:  onGetNewVersion?: () => void): (MenuItem | MenuSection)[] {
69:  const grouped = catalog.providers.length > 1;
70:  const entries: (MenuItem | MenuSection)[] = [];
71:  for (const provider of catalog.providers) {
72:    if (grouped)
73:      entries.push({ section: provider.label, detail: providerDetail(provider) });
74:    const models = [...provider.models];
75:    // The chat's model stays choosable even before its list arrives, or when
76:    // the list leaves it out. A list the server refused for this release has
77:    // nothing to choose: Get the new version… takes its place.
78:    const outdated = provider.state === 'failed' && provider.updateMessage !== undefined && onGetNewVersion !== undefined;
79:    if (provider.id === choice.provider && !outdated && !models.some((model) => model.id === choice.model))
80:      models.unshift({ id: choice.model, label: unlistedLabel(catalog, choice), efforts: [] });
