inline Slic3r::GUI::JusPrin::Agent::RecordItem kept_result(const Slic3r::GUI::JusPrin::Agent::AgentToolResult& result)
{
    Slic3r::GUI::JusPrin::Agent::RecordItem item{Slic3r::GUI::JusPrin::Agent::RecordItem::Kind::Results};
    item.results.push_back({result.call_id, result.output_json, result.state != "succeeded"});
    return item;
}

// A reply request whose record goes nowhere, for tests of one request's wire:
// every blob is written and every item dropped.
inline Slic3r::GUI::JusPrin::Agent::AgentRequest& kept_nowhere(Slic3r::GUI::JusPrin::Agent::AgentRequest& request)
{
    request.on_recorded = [](const std::string&, std::vector<Slic3r::GUI::JusPrin::Agent::RecordItem>) {};
    request.keep_blob   = [](const std::string&) -> std::optional<std::string> { return "chats/test/blob"; };
    return request;
}

inline void keep(const Slic3r::GUI::JusPrin::Agent::AgentRequest& request,
                 std::vector<Slic3r::GUI::JusPrin::Agent::RecordItem> items)
{
    if (request.on_recorded && !items.empty())
        request.on_recorded("responses", std::move(items));
}

} // namespace JusPrinTest
class RecordingAgent final : public IAgentService
{
public:
    bool ready() const override { return true; }
    bool busy() const override { return active; }
    bool start(const AgentRequest& request) override
    {
        requests.push_back(request);
        const bool title = request.purpose == AgentRequest::Purpose::ConversationTitle;
        const std::string reply = title ? "A part" : "This part came from PrusaSlicer.";
        if (!title) {
            std::vector<RecordItem> sent = JusPrinTest::kept_person_side(request);
            sent.push_back(JusPrinTest::kept_reply(reply));
            JusPrinTest::keep(request, std::move(sent));
        }
        events.push_back(AgentEvent::delta(reply));
        events.push_back(AgentEvent::completed());
        active = true;
        return true;
    }
    bool continue_after_tool(const AgentToolResult&) override { return false; }
    void cancel() override { active = false; events.clear(); }
    std::optional<AgentEvent> poll() override
    {
        if (events.empty())
            return std::nullopt;
        AgentEvent event = std::move(events.front());
        events.pop_front();
        if (event.kind == AgentEventKind::Completed || event.kind == AgentEventKind::Failed)
            active = false;
        return event;
    }

    std::vector<AgentRequest> requests;
    std::deque<AgentEvent>    events;
    bool                      active{false};
};

